def generate_elements(a, b, i_values):
    """Calculates a^2 + i*a*b + b^2 for given a, b, and i."""
    elements = set()
    for i in i_values:
        element = a**2 + i * a * b + b**2
        elements.add(element)
    return sorted(list(elements))

pairs_to_check = [(1, 2), (1, 3), (2, 3)]
i_values = [-2, -1, 0, 1, 2]

results = {}
for a, b in pairs_to_check:
    elements = generate_elements(a, b, i_values)
    results[(a, b)] = elements

for pair, elements in results.items():
    print(f"Pair {pair}: Generated elements for i in {-2, -1, 0, 1, 2} are {elements}")

