import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def enumerate_good_candidates(limit_y):
    """
    Enumerates m = x^2 + y^2 for distinct positive integers (x, y)
    where gcd(x, y) > 1, up to y=limit_y.
    """
    candidates = {}
    for y in range(2, limit_y + 1):
        for x in range(1, y): # x < y to avoid duplicates
            if gcd(x, y) > 1:
                m = x**2 + y**2
                if m not in candidates:
                    candidates[m] = (x, y)

    sorted_candidates = sorted(candidates.keys())
    return sorted_candidates

# Search up to y=50 to ensure we pass the 20th element comfortably
candidates = enumerate_good_candidates(50)
print(f"Total candidates found: {len(candidates)}")

# Check the 20th smallest candidate (index 19)
if len(candidates) >= 20:
    print(f"The 20th smallest candidate is: {candidates[19]}")
else:
